const trigger = $('Watch for Outreach Replies').item.json;
const full = $input.first().json;

function stripHtml(html) {
  return html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function parseHeaderSender(headerStr, fallback) {
  if (!headerStr) return fallback || '';
  // Headers come as "From: Name <email>" — strip the "From: " prefix
  const clean = headerStr.replace(/^From:\s*/i, '').trim();
  return clean;
}

// Strip quoted reply content (everything after "On ... wrote:")
function stripQuotedReply(text) {
  if (!text) return '';
  return text
    .replace(/\r\n/g, '\n')
    .replace(/On .+?wrote:\n[\s\S]*/s, '')
    .trim();
}

// With Simplify OFF, from/to come from headers object
const fromRaw = full.headers?.from || '';
const fromClean = parseHeaderSender(fromRaw, trigger.From);
const emailMatch = fromClean.match(/<(.+?)>/);
const fromEmail = emailMatch ? emailMatch[1] : fromClean;
const nameMatch = fromClean.match(/^"?([^"<]+)"?\s*</);
const fromName = nameMatch ? nameMatch[1].trim() : '';

const rawBody = full.text?.trim() || (full.html ? stripHtml(full.html) : '') || trigger.snippet || '';

// Strip the quoted original message so Gemini only sees the actual reply
const cleanBody = stripQuotedReply(rawBody);

return [{
  json: {
    recordId: full.id,
    threadId: full.threadId,
    from: fromClean,
    fromEmail: fromEmail,
    fromName: fromName,
    subject: full.subject || trigger.Subject,
    body: cleanBody,
    receivedAt: full.date || trigger.internalDate
  }
}];

