const item = $input.first().json;

const raw =
  item.content?.parts?.[0]?.text ||                          // direct candidate object (your current shape)
  item.candidates?.[0]?.content?.parts?.[0]?.text ||          // candidates-wrapped shape
  item.text ||
  '';

const cleaned = raw.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    classification: 'Needs Manual Review',
    confidence: 0,
    reasoning: 'AI response could not be parsed',
    suggested_reply: ''
  };
}

return {
  json: {
    ...$('Extract Email Details').item.json,
    ...parsed
  }
};

